insert into public.question_bank (teks_code, teks_item_id, subject, grade_num, course, difficulty, qtype, prompt, choices, answer_idx, explanation, source, status, gen_batch)
select distinct on (v.prompt) v.code, i.id, d.subject,
       case when i.grade_level = 'K' then 0 when i.grade_level ~ '^[0-9]+' then substring(i.grade_level from '^[0-9]+')::smallint end,
       case when i.grade_level is null then i.grade_course_title end,
       v.diff, 'mc', v.prompt, v.choices, v.ans, v.expl, v.src, 'checked', 'hs_ssadv_v1'
from (values
('113.60.c.1.A',3,'Maya loves mapping old trade routes and also enjoys writing. Which career fit would she most likely explore for a social studies research project?','["Historian or cartographer", "Electrician", "Pastry chef", "Airline mechanic"]'::jsonb,0,'Linking interests to a discipline is the first step of an advanced studies project.','original'),
('113.60.c.1.A',3,'A student who enjoys debating laws and public policy is analyzing how that interest connects to a career. Which discipline is the closest match?','["Welding", "Political science or law", "Dental hygiene", "Marine biology"]'::jsonb,1,'Matching interests to a discipline guides project choice.','original'),
('113.60.c.1.B',3,'Before choosing a topic in economics, Jalen reads a journal article, a government report and a news analysis. Why use varied sources?','["To make the paper longer", "To avoid citing anyone", "To see the topic from several viewpoints and check claims against each other", "To find only one opinion"]'::jsonb,2,'Literature review draws on varied sources.','original'),
('113.60.c.1.B',3,'Which source is the best choice for a scholarly literature review?','["A product advertisement", "A social media comment", "An anonymous blog post", "A peer-reviewed journal article"]'::jsonb,3,'Peer review adds credibility.','original'),
('113.60.c.1.C',3,'A student notices that many teens in her town cannot reach a library after school. This observation is most useful for doing what?','["Identifying a problem or concern to study", "Writing a conclusion", "Printing a poster", "Citing a source"]'::jsonb,0,'Projects start from a real problem.','original'),
('113.60.c.1.C',3,'Which statement is a clear problem statement for a social studies project?','["Transportation exists", "Teens in our county have too little access to public transportation to reach after-school jobs", "I like history", "Buses are fun"]'::jsonb,1,'A problem statement names a specific issue and group.','original'),
('113.60.c.1.D',3,'Why would a student interview a city planner before finalizing a project on local zoning?','["To avoid doing research", "To copy the planner''s work", "To learn whether the project is realistic and appropriate from a professional''s view", "To skip the proposal"]'::jsonb,2,'Professional input tests appropriateness.','original'),
('113.60.c.1.D',3,'A survey of 40 community members gives a student data on a local issue. This is an example of what?','["A secondary source", "A final presentation", "Plagiarism", "Gathering primary data to judge a project"]'::jsonb,3,'Surveys and interviews produce primary data.','original'),
('113.60.c.1.E',3,'Which item belongs in a project proposal?','["Well-defined questions, goals, rationale and procedures", "A list of favorite foods", "The final grade", "Only a title"]'::jsonb,0,'Proposals state what, why and how.','original'),
('113.60.c.1.E',3,'A proposal states, "I will measure how many residents use the new bike lane over four weeks." This part of the proposal is a what?','["Rationale", "Procedure", "Citation", "Conclusion"]'::jsonb,1,'Procedures describe the steps taken.','original'),
('113.60.c.2.A',3,'Shadowing an economist for a day helps a student do what?','["Earn a degree", "Replace the proposal", "Understand the requirements and practices of the profession through observation", "Skip research"]'::jsonb,2,'Observation builds career understanding.','original'),
('113.60.c.2.A',3,'While observing a county clerk, a student notes the training and licenses needed for the job. Why record these?','["They replace the interview", "They are a final grade", "They prove the job is easy", "They show the requirements of the profession"]'::jsonb,3,'Requirements are part of career knowledge.','original'),
('113.60.c.2.B',3,'A student uses a spreadsheet and survey software the way a market researcher would. This is an example of what?','["Simulating the methods and technologies of a field", "Avoiding technology", "Memorizing a textbook", "Copying a source"]'::jsonb,0,'Simulation lets students practice professional methods.','original'),
('113.60.c.2.B',3,'Which activity best simulates historical research methods?','["Reading only the title", "Comparing primary documents from an archive", "Skipping the sources", "Guessing the outcome"]'::jsonb,1,'Historians analyze primary documents.','original'),
('113.60.c.3.A',3,'A student wants to produce a public history exhibit. Who should help define the product?','["No one", "Only a classmate who knows nothing", "A museum curator or other appropriate professional", "A stranger online"]'::jsonb,2,'Collaboration with professionals sharpens the product.','original'),
('113.60.c.3.A',3,'Why collaborate with a professional when defining a product?','["To skip the plan", "To remove the audience", "To avoid work", "To make sure it meets real standards in the field"]'::jsonb,3,'Professional standards guide quality.','original'),
('113.60.c.3.B',3,'A plan for completing a research product with 10 weeks left should include what?','["Tasks, deadlines and needed resources", "Only the title", "No dates", "A list of hobbies"]'::jsonb,0,'Plans organize time and resources.','original'),
('113.60.c.3.B',3,'A student breaks a 12-week project into four 3-week phases. This is an example of what?','["Peer review only", "Developing a plan for completion", "Plagiarism", "A final reflection"]'::jsonb,1,'Phases support planning.','original'),
('113.60.c.3.C',3,'Why write assessment criteria before finishing a project?','["To lower standards", "To avoid feedback", "So everyone knows how success will be judged", "To hide the goals"]'::jsonb,2,'Criteria define success in advance.','original'),
('113.60.c.3.C',3,'Which is a measurable success criterion for a survey project?','["Try hard", "Do something good", "Make it nice", "At least 100 completed responses from a mix of age groups"]'::jsonb,3,'Measurable criteria can be checked.','original'),
('113.60.c.3.D',3,'A product for middle school students should use what kind of language?','["Clear, age-appropriate language and examples", "Dense legal jargon", "No explanations", "Random slang"]'::jsonb,0,'Appropriateness for the audience matters.','original'),
('113.60.c.3.D',3,'Before presenting to a city council, why consider the audience?','["To shorten the research", "To match the content and tone to what they need and expect", "To ignore them", "To avoid evidence"]'::jsonb,1,'Audience shapes the product.','original'),
('113.60.c.3.E',3,'After finishing a plan, a student begins gathering data, drafting and building. This step is called what?','["Choosing a career", "Defining the problem", "Implementing the plan", "Grading the product"]'::jsonb,2,'Implementation carries out the plan.','original'),
('113.60.c.3.E',3,'A student falls behind schedule in week 6. What is the best step in implementing the plan?','["Hide the delay", "Abandon the project", "Copy another paper", "Adjust the timeline and priorities while keeping the goals"]'::jsonb,3,'Plans can be adjusted during implementation.','original'),
('113.60.c.3.F',3,'A journal kept during a project should include what?','["Dated notes on each phase and reflections on what was learned", "Blank pages", "Unrelated drawings", "Only the final grade"]'::jsonb,0,'The journal documents the process.','original'),
('113.60.c.3.F',3,'Why record reflections in a project journal?','["To replace the presentation", "To track learning and decisions across phases", "To skip the plan", "To avoid data"]'::jsonb,1,'Reflection builds learning.','original'),
('113.60.c.4.A',3,'After a practice run, a student cuts the presentation from 20 minutes to 12 to fit the time limit. This is an example of what?','["Changing the topic", "Ignoring feedback", "Reviewing and revising the plan to present findings", "Plagiarizing"]'::jsonb,2,'Revision improves presentations.','original'),
('113.60.c.4.A',3,'Which revision best improves a presentation of survey results?','["Adding unrelated jokes", "Removing all data", "Reading every response aloud", "Adding a clear chart that shows the key finding"]'::jsonb,3,'Visuals clarify findings.','original'),
('113.60.c.4.B',3,'To present findings to a school board, a student must do what first?','["Arrange a date, time, space and equipment with the appropriate audience", "Delete the slides", "Skip the audience", "Delay the project"]'::jsonb,0,'Logistics make a presentation possible.','original'),
('113.60.c.4.B',3,'A student confirms the projector works and that the room is booked. This is an example of what?','["Collecting data", "Making arrangements for the presentation", "Citing sources", "Writing a proposal"]'::jsonb,1,'Preparation avoids problems.','original'),
('113.60.c.4.C',3,'Presenting like a professional includes what?','["Reading with the back turned", "Mumbling", "Clear organization, evidence, eye contact and appropriate dress", "Avoiding evidence"]'::jsonb,2,'Professional skills include delivery.','original'),
('113.60.c.4.C',3,'Which behavior best simulates a professional researcher''s presentation?','["Skipping methods", "Hiding sources", "Telling only a story", "Explaining methods, results and limitations"]'::jsonb,3,'Researchers present methods and results.','original'),
('113.60.c.4.D',3,'After presenting, an audience member suggests clearer labels on a graph. The best response is to do what?','["Consider the feedback and decide how to improve", "Ignore it", "Delete the graph", "Argue with the audience"]'::jsonb,0,'Feedback helps refine work.','original'),
('113.60.c.4.D',3,'Why consider feedback from an audience of professionals?','["It replaces the product", "It reveals strengths and areas for improvement", "It ends the project", "It is always wrong"]'::jsonb,1,'Professional feedback improves work.','original'),
('113.60.c.4.F',3,'At the end of a project, a student writes about what she learned and what she would change. This is an example of what?','["Collecting data", "Making a plan", "Reflecting on personal learning experiences", "Defining a problem"]'::jsonb,2,'Reflection closes the study.','original'),
('113.60.c.4.F',3,'Which question best guides a final reflection on a research project?','["How long was lunch?", "What color was the poster?", "Who sat nearest?", "What did I learn about the process and about myself?"]'::jsonb,3,'Reflection examines learning.','original')
) as v(code, diff, prompt, choices, ans, expl, src)
join public.teks_items i on i.code = v.code and i.is_standard
join public.teks_documents d on d.id = i.document_id and d.subject = 'Social Studies' and d.language = 'en'
on conflict (fingerprint) do nothing;
